"@keyframes hostRing{0%,100%{outline-color:#36c8ff;outline-offset:3px;filter:drop-shadow(0 0 4px #36c8ff)}50%{outline-color:#a8f2ff;outline-offset:6px;filter:drop-shadow(0 0 11px #36c8ff)}}",
"#tb .av .hbdg{position:absolute;right:-9px;bottom:-9px;width:20px;height:20px;border-radius:50%;display:grid;place-items:center;font-size:12px;line-height:1;font-style:normal;background:linear-gradient(#5fd8ff,#1478c8);border:2px solid #fff;box-shadow:0 1px 4px rgba(0,0,0,.6);pointer-events:none;animation:hostBadge 1.6s ease-in-out infinite alternate}",
"@keyframes hostBadge{from{transform:scale(1)}to{transform:scale(1.18)}}",
