"if(!BD.length){const a=hc[0]>>2,b=hc[1]>>2,h=Math.max(a,b),l=Math.min(a,b);s=(h+l)/32+(a===b?.35+h/50:0)+((hc[0]&3)===(hc[1]&3)?.05:0)+(h-l<=2?.03:0)}",
