"<text x=\"50\" y=\"51\" font-size=\"${txt.length>2?15:19}\" font-weight=\"900\" text-anchor=\"middle\" dominant-baseline=\"central\" fill=\"${e}\" font-family=\"Georgia,serif\">${txt}<\/text>",
