"window.__DECOR=DECOR;function ensureDecor(){const x=document.querySelector('#tb .tlx');if(!x||x.querySelector('#dcr'))return;const d=document.createElement('div');d.id='dcr';d.innerHTML=DECOR();x.prepend(d)}",
