"const di=q('#di');if(!di)return;const hs=[...document.querySelectorAll('#tb .hc')],c=hs.filter(x=>!x.classList.contains('meld')),a=c.length?c:hs,p=a[a.length-1];if(p){fs=+p.dataset.v;di.click()}}",
