"const bt=q('.bt2');if(bt&&!q('#flp')){bt.insertAdjacentHTML('beforeend','<button class=\"b2 g\" id=\"flp\">LẬT BÀI<\/button>');q('#flp').onclick=()=>{F.f=F.f.map(()=>1);snd('flip');flipDone(k,cards)}}",
