" b.classList.add('tilt');b.style.setProperty('--ry',(x*10).toFixed(1)+'deg');b.style.setProperty('--rx',(-y*8).toFixed(1)+'deg');b.style.setProperty('--px',x.toFixed(2));b.style.setProperty('--py',y.toFixed(2))};",
