"const w=Math.round((6000+Math.random()*24000)/500)*500;if(k<TLK.length)TLK[k]=w;CK[k]=w;KS[k]=Math.max(2000,w);JT[k]=Date.now();if(SES&&k===SES.ownerSeat)passHost()}",
